CREATE TABLE `standalone_validation` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `validation_code` varchar(64) NOT NULL,
  `user_id` bigint NOT NULL,
  `model_asset_id` bigint DEFAULT NULL,
  `model_path` varchar(500) DEFAULT NULL,
  `dataset_asset_id` bigint DEFAULT NULL,
  `dataset_path` varchar(500) DEFAULT NULL,
  `algorithm_type` varchar(64) NOT NULL DEFAULT 'YOLO',
  `status` varchar(32) NOT NULL DEFAULT 'PENDING',
  `progress` int NOT NULL DEFAULT '0',
  `python_job_id` varchar(64) DEFAULT NULL,
  `metrics_json` text,
  `result_file_path` varchar(500) DEFAULT NULL,
  `quality_label` varchar(32) DEFAULT NULL,
  `error_message` text,
  `finished_at` datetime DEFAULT NULL,
  `is_deleted` tinyint NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `input_mode` varchar(32) NOT NULL DEFAULT 'ASSET_REFERENCE',
  `input_root_path` varchar(500) DEFAULT NULL,
  `retain_input` tinyint NOT NULL DEFAULT '1',
  `input_cleanup_status` varchar(32) DEFAULT NULL,
  `input_cleaned_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_standalone_validation_code` (`validation_code`),
  KEY `idx_sv_user_id` (`user_id`),
  KEY `idx_sv_model_asset_id` (`model_asset_id`),
  KEY `idx_sv_dataset_asset_id` (`dataset_asset_id`),
  KEY `idx_sv_status` (`status`),
  KEY `idx_sv_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
