--
-- Table structure for table `workflow`
--

DROP TABLE IF EXISTS `workflow`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `workflow` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `workflow_code` varchar(64) NOT NULL,
  `workflow_name` varchar(128) NOT NULL,
  `initiator_user_id` bigint NOT NULL,
  `server_user_id` bigint NOT NULL,
  `client_model_asset_id` bigint DEFAULT NULL,
  `server_dataset_asset_id` bigint DEFAULT NULL,
  `client_model_count` int NOT NULL DEFAULT '1',
  `is_public` tinyint NOT NULL DEFAULT '0',
  `status` varchar(32) NOT NULL,
  `current_step` varchar(255) DEFAULT NULL,
  `progress` int NOT NULL DEFAULT '0',
  `python_job_id` varchar(64) DEFAULT NULL,
  `remark` text,
  `metrics_json` text,
  `result_file_path` varchar(500) DEFAULT NULL,
  `result_retention_status` varchar(32) NOT NULL DEFAULT 'TEMPORARY' COMMENT 'Workflow result retention state: TEMPORARY, SAVED, DELETED',
  `result_saved_at` datetime DEFAULT NULL COMMENT 'Time when user manually saved result',
  `result_deleted_at` datetime DEFAULT NULL COMMENT 'Time when result artifacts were deleted',
  `error_message` longtext,
  `is_deleted` tinyint NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `yolo_version` varchar(20) NOT NULL DEFAULT 'YOLOv10',
  `collected_model_count` int NOT NULL DEFAULT '0',
  `expected_model_count` int NOT NULL DEFAULT '1',
  `federated_status` varchar(32) NOT NULL DEFAULT 'PENDING',
  `federated_strategy` varchar(32) NOT NULL DEFAULT 'FEDML',
  `federated_model_asset_id` bigint DEFAULT NULL,
  `federated_started_at` datetime DEFAULT NULL,
  `federated_finished_at` datetime DEFAULT NULL,
  `dp_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `dp_epsilon` decimal(12,6) DEFAULT NULL COMMENT ' epsilon ',
  `dp_delta` decimal(18,12) DEFAULT NULL COMMENT ' delta ',
  `dp_clip_norm` decimal(12,6) DEFAULT NULL COMMENT ' clip norm',
  `dp_noise_multiplier` decimal(12,6) DEFAULT NULL,
  `dp_status` varchar(32) NOT NULL DEFAULT 'DISABLED' COMMENT 'DISABLED/ENABLED/RUNNING/COMPLETED/FAILED',
  `dp_summary` varchar(500) DEFAULT NULL,
  `shuffle_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `shuffle_batch_no` varchar(64) DEFAULT NULL,
  `shuffle_status` varchar(32) NOT NULL DEFAULT 'DISABLED' COMMENT 'DISABLED/WAITING/RUNNING/COMPLETED/FAILED',
  `shuffle_order_summary` varchar(500) DEFAULT NULL,
  `shuffle_started_at` datetime DEFAULT NULL,
  `shuffle_finished_at` datetime DEFAULT NULL,
  `secure_aggregation_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `secure_aggregation_mode` varchar(32) NOT NULL DEFAULT 'PLAIN' COMMENT 'PLAIN/SECURE',
  `secure_aggregation_status` varchar(32) NOT NULL DEFAULT 'DISABLED' COMMENT 'DISABLED/PREPARING/RUNNING/COMPLETED/FAILED',
  `secure_aggregation_summary` varchar(500) DEFAULT NULL,
  `secure_aggregation_started_at` datetime DEFAULT NULL,
  `secure_aggregation_finished_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_workflow_code` (`workflow_code`),
  KEY `idx_workflow_initiator_user_id` (`initiator_user_id`),
  KEY `idx_workflow_server_user_id` (`server_user_id`),
  KEY `idx_workflow_status` (`status`),
  KEY `idx_workflow_created_at` (`created_at`),
  KEY `idx_workflow_result_retention_status` (`result_retention_status`)
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

