DROP TABLE IF EXISTS `workflow_model_upload`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `workflow_model_upload` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `workflow_id` bigint NOT NULL,
  `uploader_id` bigint NOT NULL,
  `model_asset_id` bigint DEFAULT NULL,
  `server_model_asset_id` bigint DEFAULT NULL,
  `original_filename` varchar(255) NOT NULL,
  `stored_filename` varchar(255) DEFAULT NULL,
  `encrypted_file_path` varchar(500) DEFAULT NULL,
  `decrypted_file_path` varchar(500) DEFAULT NULL,
  `file_size` bigint DEFAULT NULL,
  `file_sha256` varchar(64) DEFAULT NULL,
  `aes_key_base64` varchar(512) DEFAULT NULL,
  `aes_iv_base64` varchar(100) DEFAULT NULL,
  `upload_token` varchar(64) DEFAULT NULL,
  `upload_status` varchar(20) NOT NULL DEFAULT 'PENDING',
  `error_message` longtext,
  `uploaded_at` datetime DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `token_expire_at` datetime DEFAULT NULL,
  `federated_round` int NOT NULL DEFAULT '1',
  `federated_weight` decimal(10,4) NOT NULL DEFAULT '1.0000',
  `aggregation_status` varchar(32) NOT NULL DEFAULT 'PENDING',
  `client_display_name` varchar(128) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_workflow_id` (`workflow_id`),
  KEY `idx_uploader_id` (`uploader_id`),
  KEY `idx_upload_token` (`upload_token`),
  KEY `idx_model_asset_id` (`model_asset_id`),
  KEY `idx_wmu_model_asset_id` (`model_asset_id`),
  KEY `idx_wmu_server_model_asset_id` (`server_model_asset_id`)
) ENGINE=InnoDB AUTO_INCREMENT=39 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
