CREATE TABLE `workflow_step` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `workflow_id` bigint NOT NULL,
  `step_no` int NOT NULL DEFAULT '1',
  `step_code` varchar(32) NOT NULL,
  `step_name` varchar(64) NOT NULL,
  `from_status` varchar(32) DEFAULT NULL,
  `to_status` varchar(32) NOT NULL,
  `operator_user_id` bigint DEFAULT NULL,
  `operator_role` varchar(32) DEFAULT NULL,
  `message` varchar(500) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_workflow_step_workflow_id` (`workflow_id`),
  KEY `idx_workflow_step_workflow_id_step_no` (`workflow_id`,`step_no`)
) ENGINE=InnoDB AUTO_INCREMENT=322 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
